export const SNAPSHOT_MAGIC = 0x32534252;
export const SNAPSHOT_VERSION = 2;
export const HEADER_SIZE = 112;
export const INSTRUMENTS_OFFSET = 112;
export const CYLINDERS_OFFSET = 304;
export const CYLINDER_STRIDE = 40;
export const MAX_CYLINDERS = 16;

export const INSTRUMENT_NAMES = [
  "rpm",
  "rpm_smooth",
  "cycle_rpm",
  "map",
  "torque",
  "power",
  "lambda",
  "spark",
  "idle_valve",
  "throttle",
  "throttle_area",
  "ignition",
  "starter",
  "held",
  "fuel_cut",
  "spark_cut",
  "limiter_cuts",
  "overrun_time",
  "load_torque",
  "crank_inertia",
  "air_flow",
  "fuel_flow",
  "exhaust_temperature",
  "tailpipe_temperature",
] as const;
export type InstrumentName = (typeof INSTRUMENT_NAMES)[number];

export const CYLINDER_FIELD_NAMES = [
  "pressure",
  "temperature",
  "burn",
  "intake_lift",
  "exhaust_lift",
] as const;
export type CylinderFieldName = (typeof CYLINDER_FIELD_NAMES)[number];

/** The bytes of a snapshot of n cylinders. */
export function snapshotSize(cylinders: number): number {
  return CYLINDERS_OFFSET + CYLINDER_STRIDE * cylinders;
}

export interface SnapshotHeader {
  magic: number;
  version: number;
  size: number;
  cylinders: number;
  instruments: number;
  cylinder_fields: number;
  reserved0: number;
  reserved1: number;
  build_id: bigint;
  generation: number;
  sequence: number;
  physics_tick: number;
  audio_frame: number;
  cycle_index: number;
  physics_hz: number;
  audio_hz: number;
  phase_rad: number;
  speed_rad_s: number;
}

export type CylinderState = Record<CylinderFieldName, number>;

/**
 * One snapshot, decoded: the header's fields, then the instruments by name (in place of the
 * header's count of them, as snapshot_v2.py's `parse` has it) and the cylinders.
 */
export interface Snapshot extends Omit<SnapshotHeader, "instruments"> {
  instruments: Record<InstrumentName, number>;
  cylinder: CylinderState[];
}

/** A snapshot the contract's rules refuse. */
export class SnapshotError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "SnapshotError";
  }
}

function fail(why: string): never {
  throw new SnapshotError(why);
}

/** A 64-bit counter as a number; one past 2^53 is refused, not rounded. */
function counter(view: DataView, offset: number, name: string): number {
  const v = view.getBigUint64(offset, true);
  if (v > BigInt(Number.MAX_SAFE_INTEGER)) fail(`${name} does not fit in a number`);
  return Number(v);
}

/** Reads one snapshot, checked on its own by the contract's rules (snapshot_v2.py's `parse`). */
export function decodeSnapshot(bytes: ArrayBuffer | ArrayBufferView): Snapshot {
  // isView, not instanceof: bytes that crossed a MessagePort may come from another realm
  const view = ArrayBuffer.isView(bytes)
    ? new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength)
    : new DataView(bytes);
  if (view.byteLength < HEADER_SIZE) fail("shorter than the header");
  const h: SnapshotHeader = {
    magic: view.getUint32(0, true),
    version: view.getUint32(4, true),
    size: view.getUint32(8, true),
    cylinders: view.getUint32(12, true),
    instruments: view.getUint32(16, true),
    cylinder_fields: view.getUint32(20, true),
    reserved0: view.getUint32(24, true),
    reserved1: view.getUint32(28, true),
    build_id: view.getBigUint64(32, true),
    generation: counter(view, 40, "generation"),
    sequence: counter(view, 48, "sequence"),
    physics_tick: counter(view, 56, "physics_tick"),
    audio_frame: counter(view, 64, "audio_frame"),
    cycle_index: counter(view, 72, "cycle_index"),
    physics_hz: view.getFloat64(80, true),
    audio_hz: view.getFloat64(88, true),
    phase_rad: view.getFloat64(96, true),
    speed_rad_s: view.getFloat64(104, true),
  };
  if (h.magic !== SNAPSHOT_MAGIC) fail(`magic ${h.magic.toString(16)}, not RBS2`);
  if (h.version !== SNAPSHOT_VERSION) fail(`version ${h.version}, not ${SNAPSHOT_VERSION}`);
  if (h.instruments !== INSTRUMENT_NAMES.length || h.cylinder_fields !== CYLINDER_FIELD_NAMES.length) {
    fail("instruments or cylinder fields aren't this version's");
  }
  if (h.cylinders < 1 || h.cylinders > MAX_CYLINDERS) fail(`${h.cylinders} cylinders`);
  if (h.reserved0 !== 0 || h.reserved1 !== 0) fail("reserved words not 0");
  const need = snapshotSize(h.cylinders);
  if (h.size !== need || view.byteLength !== need) fail(`size ${h.size}, the layout needs ${need}`);
  for (const name of ["physics_hz", "audio_hz"] as const) {
    if (!(Number.isFinite(h[name]) && h[name] > 0)) fail(`${name} ${h[name]}`);
  }
  if (!(h.phase_rad >= 0 && h.phase_rad < 4 * Math.PI)) fail(`phase ${h.phase_rad} outside [0, 4 pi)`);
  if (!(Number.isFinite(h.speed_rad_s) && h.speed_rad_s >= 0)) fail(`speed ${h.speed_rad_s}`);
  const instruments = {} as Record<InstrumentName, number>;
  INSTRUMENT_NAMES.forEach((name, i) => {
    const v = view.getFloat64(INSTRUMENTS_OFFSET + 8 * i, true);
    if (!Number.isFinite(v)) fail("an instrument isn't a number");
    instruments[name] = v;
  });
  const cylinder: CylinderState[] = [];
  for (let c = 0; c < h.cylinders; c++) {
    const row = {} as CylinderState;
    CYLINDER_FIELD_NAMES.forEach((name, f) => {
      row[name] = view.getFloat64(CYLINDERS_OFFSET + CYLINDER_STRIDE * c + 8 * f, true);
    });
    if (!(row.pressure > 0 && row.temperature > 0)) fail(`cylinder ${c}: pressure and temperature must be positive`);
    if (!(row.burn >= 0 && row.burn <= 1)) fail(`cylinder ${c}: burn fraction ${row.burn}`);
    if (!(row.intake_lift >= 0 && row.exhaust_lift >= 0)) fail(`cylinder ${c}: a negative valve lift`);
    cylinder.push(row);
  }
  return { ...h, instruments, cylinder };
}

/**
 * Writes a snapshot in the layout (the fake add-on's and the tests' side). The header's
 * `size`, `magic`, `version` and counts are the layout's, whatever `s` says.
 */
export function encodeSnapshot(s: Snapshot): ArrayBuffer {
  const n = s.cylinder.length;
  const buffer = new ArrayBuffer(snapshotSize(n));
  const view = new DataView(buffer);
  const h: SnapshotHeader = {
    ...s,
    magic: SNAPSHOT_MAGIC,
    version: SNAPSHOT_VERSION,
    size: buffer.byteLength,
    cylinders: n,
    instruments: INSTRUMENT_NAMES.length,
    cylinder_fields: CYLINDER_FIELD_NAMES.length,
    reserved0: 0,
    reserved1: 0,
  };
  view.setUint32(0, h.magic, true);
  view.setUint32(4, h.version, true);
  view.setUint32(8, h.size, true);
  view.setUint32(12, h.cylinders, true);
  view.setUint32(16, h.instruments, true);
  view.setUint32(20, h.cylinder_fields, true);
  view.setUint32(24, h.reserved0, true);
  view.setUint32(28, h.reserved1, true);
  view.setBigUint64(32, h.build_id, true);
  view.setBigUint64(40, BigInt(h.generation), true);
  view.setBigUint64(48, BigInt(h.sequence), true);
  view.setBigUint64(56, BigInt(h.physics_tick), true);
  view.setBigUint64(64, BigInt(h.audio_frame), true);
  view.setBigUint64(72, BigInt(h.cycle_index), true);
  view.setFloat64(80, h.physics_hz, true);
  view.setFloat64(88, h.audio_hz, true);
  view.setFloat64(96, h.phase_rad, true);
  view.setFloat64(104, h.speed_rad_s, true);
  INSTRUMENT_NAMES.forEach((name, i) => view.setFloat64(INSTRUMENTS_OFFSET + 8 * i, s.instruments[name], true));
  s.cylinder.forEach((row, c) => {
    CYLINDER_FIELD_NAMES.forEach((name, f) => {
      view.setFloat64(CYLINDERS_OFFSET + CYLINDER_STRIDE * c + 8 * f, row[name], true);
    });
  });
  return buffer;
}
